import 'package:supabase_flutter/supabase_flutter.dart';
class DeviceRecord{const DeviceRecord({required this.id,required this.name,required this.code,required this.active});final String id,name,code;final bool active;factory DeviceRecord.fromMap(Map<String,dynamic> r)=>DeviceRecord(id:r['id'] as String,name:r['device_name'] as String,code:r['device_code'] as String,active:r['is_active'] as bool);}
class DeviceRepository{final _c=Supabase.instance.client;Future<List<DeviceRecord>> load(String businessId)async{final rows=await _c.from('irkop_cell_devices').select('id,device_name,device_code,is_active').eq('business_id',businessId).order('created_at');return rows.map<DeviceRecord>((r)=>DeviceRecord.fromMap(r)).toList();}Future<void> create({required String businessId,required String name,required String code})=>_c.from('irkop_cell_devices').insert({'business_id':businessId,'device_name':name.trim(),'device_code':code.trim().toUpperCase()});Future<void> active({required String id,required String businessId,required bool value})=>_c.from('irkop_cell_devices').update({'is_active':value}).eq('id',id).eq('business_id',businessId);}
